INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Laptops immer weniger leistungsstark als Desktops sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "High-End-Laptops können mithalten"}, {"text": "Ja", "correct": false, "because": "Abhängig von Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen Laptop für IT-Aufgaben auswähle?', 3, '[{"text": "Prozessorleistung", "correct": true, "because": "Entscheidend für Performance"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}, {"text": "Farbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen einen Laptop für IT-Arbeit nützlich?', 5, '[{"text": "Hoher RAM", "correct": true, "because": "Unterstützt Multitasking"}, {"text": "SSD-Speicher", "correct": true, "because": "Erhöht Geschwindigkeit"}, {"text": "Großer Bildschirm", "correct": false, "because": "Nicht zwingend"}, {"text": "Bunte Tastatur", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Laptops haben meist weniger RAM als Desktops. b) Sie sind immer mobiler.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "RAM variiert, Mobilität ist Kernmerkmal"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Laptop für Netzwerkadministration kaufe?', 4, '[{"text": "Prozessor", "correct": false, "because": "Wichtig für Leistung"}, {"text": "Anschlüsse", "correct": false, "because": "Nötig für Netzwerk"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Laptops immer eine kürzere Akkulaufzeit als Tablets haben?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Modell"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich einen Laptop für IT-Schulungen nutze?', 3, '[{"text": "Portabilität", "correct": true, "because": "Ermöglicht Mobilität"}, {"text": "Maximale Lautstärke", "correct": false, "because": "Sekundär"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei einem Laptop für Programmierung entscheidend?', 5, '[{"text": "CPU-Leistung", "correct": true, "because": "Für schnelle Kompilierung"}, {"text": "RAM-Größe", "correct": true, "because": "Unterstützt Multitasking"}, {"text": "Bildschirmhelligkeit", "correct": false, "because": "Weniger relevant"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Laptops können virtualisierte Umgebungen hosten. b) Sie sind immer langsamer als Desktops. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Laptop für IT-Aufgaben auszuwählen?', 4, '[{"text": "SSD-Speicher", "correct": false, "because": "Fördert Geschwindigkeit"}, {"text": "Prozessorleistung", "correct": false, "because": "Kernkomponente"}, {"text": "Designer-Look", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Laptops immer teurer als Desktops mit gleicher Leistung?', 2, '[{"text": "Ja", "correct": true, "because": "Mobilität erhöht Kosten"}, {"text": "Nein", "correct": false, "because": "Abhängig von Konfiguration"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Laptop für IT-Administration?', 4, '[{"text": "Mobilität", "correct": true, "because": "Ermöglicht Arbeit vor Ort"}, {"text": "Einfache Wartung", "correct": true, "because": "Integrierte Hardware"}, {"text": "Hohe Lautstärke", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Laptops keine Server ersetzen können. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können als Server dienen"}, {"text": "Ja", "correct": false, "because": "Abhängig von Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen Laptop für IT-Tests auszuwählen?', 3, '[{"text": "Hohe RAM-Kapazität", "correct": true, "because": "Unterstützt Testumgebungen"}, {"text": "Großer Bildschirm", "correct": false, "because": "Nicht primär"}, {"text": "Leichtes Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Laptops sind für mobile IT-Arbeit ideal. b) Sie haben immer schwächere GPUs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GPU variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei einem Laptop für Netzwerktests?', 5, '[{"text": "Ethernet-Port", "correct": true, "because": "Für stabile Verbindung"}, {"text": "Prozessorleistung", "correct": true, "because": "Für Analysen"}, {"text": "Bildschirmfarbe", "correct": false, "because": "Irrelevant"}, {"text": "Gewicht", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen Laptop für IT-Schulungen kaufe?', 3, '[{"text": "Akkulaufzeit", "correct": false, "because": "Wichtig für Mobilität"}, {"text": "RAM-Größe", "correct": false, "because": "Unterstützt Software"}, {"text": "Tastaturbeleuchtung", "correct": true, "because": "Nice-to-have"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Haben Laptops immer weniger Anschlüsse als Desktops?', 3, '[{"text": "Ja", "correct": true, "because": "Kompaktheit reduziert Ports"}, {"text": "Nein", "correct": false, "because": "Abhängig von Modell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Laptops für Virtualisierung ungeeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Mit genug RAM möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist entscheidend, wenn ich einen Laptop für IT-Entwicklung kaufe?', 4, '[{"text": "Hohe CPU-Leistung", "correct": true, "because": "Für schnelle Builds"}, {"text": "Leichtbauweise", "correct": false, "because": "Sekundär"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]');
